pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract TokenMock {
    bool private _secondRevert;
    uint256 public balance0;
    uint256 public balance1;

    function transferFrom(address, address to, uint256 amount) external returns (bool) {
        if (!_secondRevert) {
            _secondRevert = true;
            if (to == address(0x1)) balance0 += amount;
            if (to == address(0x2)) balance1 += amount;
            return true;
        } else {
            return false;
        }
    }
}

contract InvMutTest is Test {
    C c;
    TokenMock token;

    function setUp() public {
        token = new TokenMock();
        c = new C();
    }

    function testRegression_property() public {
        address from = address(0x100);
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);

        // The reference will revert because the second transferFrom returns false, buggy version returns true
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, address(token), tos, 1));
        assertTrue(!ok, "Expected revert with reference, but call succeeded");
    }
}

